// Used in the default branch of a switch that must handle every case.
export function assertNever(value) {
  throw new Error('Unhandled value: ' + String(value));
}

import { assertNever } from './never.ts';

// A teammate added LAB_CLOSED to the list of slot codes.
export type SlotCode = 'OFF_GRID' | 'END_BEFORE_START' | 'OUTSIDE_HOURS' | 'TOO_LONG' | 'LAB_CLOSED';

export function slotMessage(code: SlotCode): string {
  switch (code) {
    case 'OFF_GRID': return 'Start and end must be on the 30-minute grid.';
    case 'END_BEFORE_START': return 'The end time must be after the start time.';
    case 'OUTSIDE_HOURS': return 'LabFlow is open from 07:00 to 21:00.';
    case 'TOO_LONG': return 'A booking can last at most 4 hours.';
    default: return 'Something is wrong with this slot.';
  }
}

import { assertNever } from '../src/never.ts';

type Status = 'PENDING' | 'CONFIRMED' | 'CANCELLED';

export function label(status: Status): string {
  switch (status) {
    case 'PENDING': return 'Waiting';
    case 'CONFIRMED': return 'Confirmed';
    default: return assertNever(status); // expect TS2345
  }
}

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { slotMessage } from '../src/messages.ts';
import { assertNever } from '../src/never.ts';

test('every code has its own message', () => {
  assert.match(slotMessage('TOO_LONG'), /4 hours/);
  assert.match(slotMessage('LAB_CLOSED'), /closed/);
});
test('assertNever throws at runtime if a bad value slips in', () => {
  assert.throws(() => assertNever('X' as never), /Unhandled value: X/);
});

