// A lab's day starts with no bookings; bookings are pushed in during the day.
export function emptyDay(lab: string) {
  return { lab, bookings: [] };
}

import { emptyDay } from '../src/day.ts';

const day = emptyDay('BE-201');
day.bookings.push({ start: '08:00', end: '10:00', minutes: 120 });
const total: number = day.bookings.reduce((sum, b) => sum + b.minutes, 0);
export { total };

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { emptyDay } from '../src/day.ts';

test('a new day has the lab and no bookings', () => {
  assert.deepEqual(emptyDay('AL-301'), { lab: 'AL-301', bookings: [] });
});
test('two days do not share one list', () => {
  const a = emptyDay('BE-201');
  const b = emptyDay('BE-201');
  a.bookings.push({ start: '08:00', end: '09:00', minutes: 60 });
  assert.equal(b.bookings.length, 0);
});

