// A lab's day starts with no bookings; bookings are pushed in during the day.
// Say what the empty list will hold — otherwise tsc types it never[] and nothing can be pushed.
export type DayBooking = { start: string; end: string; minutes: number };
export type LabDay = { lab: string; bookings: DayBooking[] };

export function emptyDay(lab: string): LabDay {
  return { lab, bookings: [] };
}

