// Write one line to the audit log. Callers should not depend on what it returns.
export function audit(action, id) {
  console.log('[audit] ' + action + ' booking ' + id);
  return true;
}

import { audit } from '../src/audit.ts';

if (audit('cancel', 7)) console.log('done'); // expect TS1345
audit('cancel', '7'); // expect TS2345

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { audit } from '../src/audit.ts';

test('audit prints one line and returns nothing', (t) => {
  const lines: string[] = [];
  t.mock.method(console, 'log', (line: string) => { lines.push(line); });
  const result: unknown = audit('cancel', 7);
  assert.deepEqual(lines, ['[audit] cancel booking 7']);
  assert.equal(result, undefined);
});

